q("kt","I hvilken konvensjon er retten til privatliv blant annet forankret?","In which convention is the right to privacy anchored?",["Den europeiske menneskerettighetskonvensjonen (EMK)","The European Convention on Human Rights (EMK)"],["NATO-avtalen","The NATO treaty"],["EØS-avtalen","The EEA agreement"]);
