q("ny","Hvem er overføringsflyktninger (kvoteflyktninger)?","Who are resettlement (quota) refugees?",["Flyktninger som kommer etter avtale med FN (UNHCR)","Refugees who come by agreement with the UN (UNHCR)"],["Personer som kommer for å jobbe","People who come to work"],["Studenter fra EU","Students from the EU"]);
