q("ny","Etter hvor lang tid kan man vanligvis søke om permanent oppholdstillatelse?","After how long can you usually apply for permanent residence?",["Etter tre eller fem år","After three or five years"],["Etter ett år","After one year"],["Etter femten år","After fifteen years"]);
