q("fa","Hvilken lov sier mye om foreldrenes plikter og barnas rettigheter?","Which law covers parents' duties and children's rights?",["Barneloven","The Children Act"],["Arbeidsmiljøloven","The Working Environment Act"],["Ferieloven","The Holiday Act"]);
