q("fa","Hva kan et barn som har fylt 15 år, bestemme selv?","What can a child aged 15 decide alone?",["Spørsmål om utdanning og innmelding i organisasjoner","Education and joining or leaving organisations"],["Å gifte seg","Getting married"],["Å stemme ved stortingsvalg","Voting in national elections"]);
q("fa","Hva er myndighetsalderen i Norge?","What is the age of majority in Norway?",["18 år","18"],["16 år","16"],["21 år","21"],"Da kan man inngå juridiske avtaler og styre egne penger.","You can then sign legal contracts and control your own money.");
q("fa","Hva forbyr barneloven i barneoppdragelsen?","What does the Children Act forbid in upbringing?",["All bruk av vold","Any use of violence"],["Å sende barna i barnehage","Sending children to kindergarten"],["Å la barna ha fritidsaktiviteter","Letting children do activities"]);
q("fa","Hva er barnevernets viktigste oppgave?","What is the child welfare service's most important task?",["Å beskytte barna, helst i samarbeid med familien","Protecting children, preferably together with the family"],["Å straffe foreldre","Punishing parents"],["Å drive skoler","Running schools"]);
q("fa","Hvem har plikt til å melde fra til barnevernet ved mistanke om vold i familien?","Who must report suspected family violence to child welfare?",["Alle som jobber med barn","Everyone who works with children"],["Ingen","Nobody"],["Bare politiet","Only the police"],"Alle som er bekymret for et barn, bør melde fra.","Anyone worried about a child should report it.");
q("fa","Hvilket nummer har alarmtelefonen for barn og unge?","What is the number of the emergency helpline for children and young people?",["116 111","116 111"],["113","113"],["116 117","116 117"],"Den er åpen kveld, natt og helg.","It is open evenings, nights and weekends.");
q("fa","Hva var Norge det første landet i verden til å opprette?","What was Norway the first country in the world to create?",["Et offentlig barnevern","A public child welfare service"],["Et nasjonalt parlament","A national parliament"],["En statskirke","A state church"],"Den første loven, vergerådsloven, trådte i kraft i 1900.","The first law came into force in 1900.");
q("fa","Hva er viktigst i en «jeg-kultur»?","What matters most in an 'I-culture'?",["Enkeltmennesket","The individual"],["Gruppa","The group"],["Lydighet mot de eldste","Obedience to elders"],"I en vi-kultur er gruppa viktigst.","In a we-culture the group matters most.");
q("fa","Hvem har foreldreansvaret for barn født fra 1. januar 2020?","Who has parental responsibility for children born from 1 January 2020?",["Begge foreldrene i utgangspunktet, også om de ikke bor sammen","Both parents by default, even if they don't live together"],["Bare moren","Only the mother"],["Bare foreldre som er gift","Only married parents"]);
q("fa","Hva er en husholdning?","What is a household?",["Mennesker som bor i samme bolig og har felles økonomi","People who share a home and finances"],["Alle i samme slekt","Everyone in the same extended family"],["Alle som bor i samme kommune","Everyone in the same municipality"]);
q("fa","Hvem kan bli bedt om hjelp fra barnevernet, for eksempel avlastning eller veiledning?","Who can ask child welfare for help, such as respite or guidance?",["Foreldrene selv","The parents themselves"],["Bare skolen","Only the school"],["Bare politiet","Only the police"]);
q("fa","Hvem har hovedansvaret for oppdragelsen av barn?","Who has the main responsibility for raising children?",["Foreldrene","The parents"],["Skolen","The school"],["Barnevernet","Child welfare"]);

