q("fr","Hva er dugnad?","What is dugnad?",["Frivillig, ubetalt arbeid som gjøres i fellesskap","Voluntary, unpaid work done together"],["Betalt overtid","Paid overtime"],["En kristen helligdag","A Christian holiday"]);
